      <div class="card rt-topics">${E.map(f=>`<details class="rt-topic" data-topic="${D(f.t)}"><summary>${Y(f.ic,"s")}<span>${f.t}</span><span class="chev">${Y("left","s")}</span></summary><div class="rt-body">${f.b(w)}<div class="tiny">${se(typeof f.gov=="function"?f.gov():f.gov)}${f.l()}</div></div></details>`).join("")}</div>
